    isBinaryish(n.left) && shouldFlatten(n.operator, n.left.operator);

  if (
    shouldNotIndent ||
    (shouldInlineLogicalExpression(n) && !samePrecedenceSubExpression) ||
    (!shouldInlineLogicalExpression(n) && shouldIndentIfInlining)
  ) {
    return group(parts);
  }

